class Solution {
public:
    int mostProfitablePath(std::vector<std::vector<int>>& edges, int bob, std::vector<int>& amount) {
        int n = amount.size();
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<int> bob_time(n, -1);
        std::vector<int> path;
        auto find_bob = [&](auto& self, int u, int p) -> bool {
            path.push_back(u);
            if (u == 0) return true;
            for (int v : adj[u]) {
                if (v != p && self(self, v, u)) return true;
            }
            path.pop_back();
            return false;
        };
        find_bob(find_bob, bob, -1);
        for (size_t t = 0; t < path.size(); ++t) bob_time[path[t]] = t;
        int ans = -1e9;
        auto dfs_alice = [&](auto& self, int u, int p, int t, int current_sum) -> void {
            if (bob_time[u] == -1 || t < bob_time[u]) current_sum += amount[u];
            else if (t == bob_time[u]) current_sum += amount[u] / 2;
            bool is_leaf = true;
            for (int v : adj[u]) {
                if (v != p) {
                    is_leaf = false;
                    self(self, v, u, t + 1, current_sum);
                }
            }
            if (is_leaf) ans = std::max(ans, current_sum);
        };
        dfs_alice(dfs_alice, 0, -1, 0, 0);
        return ans;
    }
};

class Solution {
    private int maxProfit = Integer.MIN_VALUE;
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] bobTime = new int[n];
        java.util.Arrays.fill(bobTime, -1);
        java.util.List<Integer> path = new java.util.ArrayList<>();
        findBob(bob, -1, adj, path);
        for (int t = 0; t < path.size(); t++) bobTime[path.get(t)] = t;
        maxProfit = Integer.MIN_VALUE;
        dfsAlice(0, -1, 0, 0, adj, bobTime, amount);
        return maxProfit;
    }
    private boolean findBob(int u, int p, java.util.List<Integer>[] adj, java.util.List<Integer> path) {
        path.add(u);
        if (u == 0) return true;
        for (int v : adj[u]) {
            if (v != p && findBob(v, u, adj, path)) return true;
        }
        path.remove(path.size() - 1);
        return false;
    }
    private void dfsAlice(int u, int p, int t, int sum, java.util.List<Integer>[] adj, int[] bobTime, int[] amount) {
        if (bobTime[u] == -1 || t < bobTime[u]) sum += amount[u];
        else if (t == bobTime[u]) sum += amount[u] / 2;
        boolean isLeaf = true;
        for (int v : adj[u]) {
            if (v != p) {
                isLeaf = false;
                dfsAlice(v, u, t + 1, sum, adj, bobTime, amount);
            }
        }
        if (isLeaf) maxProfit = Math.max(maxProfit, sum);
    }
}

var mostProfitablePath = function(edges, bob, amount) {
    const n = amount.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const bobTime = new Array(n).fill(-1);
    const path = [];
    const findBob = (u, p) => {
        path.push(u);
        if (u === 0) return true;
        for (const v of adj[u]) {
            if (v !== p && findBob(v, u)) return true;
        }
        path.pop();
        return false;
    };
    findBob(bob, -1);
    for (let t = 0; t < path.length; t++) bobTime[path[t]] = t;
    let ans = -Infinity;
    const dfsAlice = (u, p, t, sum) => {
        if (bobTime[u] === -1 || t < bobTime[u]) sum += amount[u];
        else if (t === bobTime[u]) sum += Math.floor(amount[u] / 2);
        let isLeaf = true;
        for (const v of adj[u]) {
            if (v !== p) {
                isLeaf = false;
                dfsAlice(v, u, t + 1, sum);
            }
        }
        if (isLeaf) ans = Math.max(ans, sum);
    };
    dfsAlice(0, -1, 0, 0);
    return ans;
};
